events.detail:
{
    valid: boolean;
    validationMessage: string;
    flags: Record<string, boolean>;
  }

methods.returnType:
Promise<{
    valid: boolean;
    validationMessage: string;
    flags: Record<string, boolean>;
  }>

children.source:
supportingMessage && (
          <span
            id={`${this.uid}-support`}
            ref={(el) => { this.supportEl = el; }}
            part="supporting-text"
            role={hasError ? 'alert' : undefined}
            class={{
              'md-checkbox__support': true,
              'md-checkbox__support--error': hasError,
            }}
          >
            {supportingMessage}
          </span>
        )
